 const [started,setStarted]=useState(false),[i,setI]=useState(0),[ans,setAns]=useState({}),[mark,setMark]=useState({}),[time,setTime]=useState(900),[done,setDone]=useState(false),[previous,setPrevious]=useState(null),[solI,setSolI]=useState(0),[showSolutions,setShowSolutions]=useState(false);
